update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"chiffres","chiffres":[{"valeur":"1 automaticien dédié","libelle":"Un spécialiste SIEMENS à temps plein sur le site, le même du début à la fin."},{"valeur":"T2 et T3 2025","libelle":"Durée de la présence sur site, du démarrage de la ligne jusqu''à sa stabilisation."},{"valeur":"10 %","libelle":"Part des candidats retenus, après entretien technique et comportemental."},{"valeur":"24/24 et 7/7","libelle":"Astreinte mobilisable pendant la mise en route, en complément de la présence sur site."},{"valeur":"Fiabiliser les installations neuves","libelle":", avant que les défauts de jeunesse ne s''installent."},{"valeur":"Optimiser les performances","libelle":"dès les premières semaines de mise en route."},{"valeur":"Vous obtenez la compétence exacte, pas un renfort généraliste.","libelle":"L''automaticien travaille sur les systèmes SIEMENS de l''installation."},{"valeur":"Vous traitez les défauts au fil de l''eau.","libelle":"L''accompagnement en fiabilisation se fait sur place, pendant la mise en route."},{"valeur":"Vous couvrez aussi l''exploitation courante.","libelle":"La mission porte sur la fiabilisation, l''amélioration et la maintenance de la ligne."},{"valeur":"Vous gardez le même intervenant du début à la fin.","libelle":"La présence est continue sur plusieurs semaines, sans rupture de suivi."},{"valeur":"Vous n''avez rien à former.","libelle":"La compétence est immédiatement exploitable sur le terrain."},{"valeur":"La prise en main de l''automatisme SIEMENS","libelle":"s''est faite rapidement."},{"valeur":"La réactivité a augmenté","libelle":"en cas de besoin technique sur l''installation."},{"valeur":"Les équipes MERSEN ont été soutenues directement","libelle":"pendant la phase sensible du démarrage."}],"reponse":[{"texte":"MERSEN avait un objectif double."},{"texte":"Les deux réclament la même chose : une compétence automatisme précise, disponible sur place, tout de suite. Ce profil ne se trouve pas au pied levé, et l''équipe interne d''un site en montée en charge est déjà prise."},{"texte":"Un démarrage de ligne concentre les défauts sur quelques semaines. Chaque arrêt non compris à ce moment-là se réinstalle ensuite dans l''exploitation courante."},{"texte":"Faire venir l''intégrateur à chaque incident coûte cher et laisse le site sans compétence propre. Un automaticien présent en continu traite le défaut et laisse la connaissance derrière lui."},{"texte":"Ce que l''intervention a permis, tel que le dossier le documente."},{"texte":"Le dossier retient un besoin métier précis, servi par une compétence immédiatement exploitable sur le terrain."},{"texte":"> [Sécuriser le démarrage de ma ligne](/contact/)"},{"texte":"Appelez le **04 78 33 72 05** du lundi au vendredi, 8h00 à 18h30 : le rappel se fait dans l''heure. Pendant une mise en route, l''astreinte 24/24 et 7/7 peut être ajoutée au contrat."},{"texte":"Nos automaticiens SIEMENS et Schneider sont évalués avant d''être proposés, en entretien technique et comportemental. Le taux de sélection est de 10 %, et les résultats vous sont transmis."},{"texte":"Sur une ligne neuve, vous savez donc qui arrive et ce qui a été vérifié, avant la première journée de mise en route."},{"texte":"> À lire aussi : [Étude de cas ERIKS : pilotage du service maintenance](/preuves/eriks/)"}]}]'::jsonb) where path = '/preuves/mersen/';
